public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Check if the target graph is already a complete bipartite graph
    if (isCompleteBipartiteGraph(target)) {
        return;
    }

    // Get the set of vertices in the target graph
    Set<V> vertices = target.vertexSet();

    // Create a queue for breadth-first search
    Queue<V> queue = new LinkedList<>();

    // Add the vertices in the result map to the queue
    for (String vertexString : resultMap.keySet()) {
        V vertex = resultMap.get(vertexString);
        if (vertex != null) {
            queue.add(vertex);
        }
    }

    // Perform breadth-first search to find all reachable vertices
    while (!queue.isEmpty()) {
        V vertex = queue.remove();
        if (!vertices.contains(vertex)) {
            target.addVertex(vertex);
            vertices.add(vertex);
            queue.addAll(getNeighbors(vertex, resultMap));
        }
    }

    // Add edges between vertices in the two sets
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (vertex1 != vertex2 && !target.containsEdge(vertex1, vertex2)) {
                target.addEdge(vertex1, vertex2);
            }
        }
    }
}

