    Iterator<E> it = tour.iterator();
    if(it.hasNext()){
        E edge = it.next();
        path.addEdge(edge.getOutVertex(), edge.getInVertex());
    }
    while(it.hasNext()){
        E edge = it.next();
        path.addEdge(edge.getInVertex(), edge.getOutVertex());
    }
    return path;
