private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Move all vertices from the bucket with label 'minLabel' to the bucket with label 0
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    for (int vertex : minLabelBucket) {
        labels.set(vertex, 0);
        bucketsByLabel.get(0).add(vertex);
    }

    // Clear the bucket with label 'minLabel'
    minLabelBucket.clear();

    // Update the labeling accordingly
    for (int label = 0; label < bucketsByLabel.size(); label++) {
        if (label != minLabel && !bucketsByLabel.get(label).isEmpty()) {
            Set<Integer> currentLabelBucket = bucketsByLabel.get(label);
            for (int vertex : currentLabelBucket) {
                labels.set(vertex, label);
            }
        }
    }
}

public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    bucketsByLabel.get(0).addAll(bucketsByLabel.get(minLabel));
    bucketsByLabel.get(minLabel).clear();
    labels.replaceAll(i -> i == minLabel ? 0 : i);
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        Set<Integer> bucket = bucketsByLabel.get(i);
        if (i == minLabel) {
            for (int vertex : bucket) {
                labels.set(vertex, 0);
            }
            bucketsByLabel.set(i, Collections.emptySet());
        } else {
            for (int vertex : bucket) {
                labels.set(vertex, i);
            }
        }
    }
}

void function (List < Set < Integer >> bucketsByLabel, List < Integer > labels, int minLabel ) {
for (int i = minLabel; i < labels.size ( ); i++) {
if (bucketsByLabel.get (i).isEmpty ( )) {
labels.set (i, 0 );
bucketsByLabel.get (0).addAll (bucketsByLabel.get (i));
bucketsByLabel.set (i, new Hashset < Integer > ( ));
}
