private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the input graph and vertices are null
    if (graph == null || vertices == null) {
        return false;
    }

    // Get the adjacency matrix of the graph
    int[][] adjMatrix = graph.getAdjacencyMatrix();

    // Initialize a set to store the neighbors of the vertices in the induced subgraph
    Set<V> neighbors = new HashSet<>();

    // Iterate over the vertices in the induced subgraph
    for (V vertex : vertices) {
        // Get the neighbors of the current vertex in the induced subgraph
        for (int i = 0; i < adjMatrix.length; i++) {
            if (adjMatrix[vertex][i] == 1) {
                neighbors.add(i);
            }
        }
    }

    // Check if the induced subgraph is a clique
    return neighbors.containsAll(vertices);
}

