    // Check if the class is already loaded
    Class result = null;
    if (loadedClasses.containsKey(className)) {
        return loadedClasses.get(className);
    }

    // If not, try to load the class from the current classpath
    try {
        result = Class.forName(className);
    } catch (ClassNotFoundException e) {
        // Class not found, try to load it from the parent classloader
        if (getParent() != null) {
            result = getParent().findClass(className);
